// Extra test cases Submit runs after the examples, generated by scripts/hidden-tests (see problems.js there).
// The file is about 250 KB, so it loads on the first Submit rather than with the app.

let loaded = null;

/** Hidden cases for a problem slug, in the editor's test-case shape; [] when there are none or offline */
export async function hiddenTestsFor(slug) {
  if (!slug) return [];
  try {
    loaded ||= import('./hiddenTests.json').then((m) => m.default);
    return (await loaded)[slug] || [];
  } catch {
    loaded = null; // try again next time, e.g. after a failed chunk download
    return [];
  }
}
